INSERT INTO public.data VALUES (98, 'Парк имени 300-летия города Таганрога', 'Места', 'Парки, сады и скверы', 'Парк имени 300-летия Таганрога располагается в районе Русское поле. Создан в апреле 1998 года решением первого мэра Таганрога С. И. Шило в память о 300-летнем юбилее города.

В 2022 году проведена масштабная реконструкция, в результате которой на территории парка появились спортивные площадки, место для тренировок и выступлений скейтбордистов, детская локация, велодорожка по периметру всего парка,', 'ул. Сергея Шило, 210', '07:00:00 00:00:00', NULL, 5.0, NULL, NULL, NULL, 'Таганрог', 47.22265499, 38.85553617);
INSERT INTO public.data VALUES (77, 'Памятник  А.С. Пушкину', 'Места', 'Памятники и мемориалы ', 'Памятник А.С. Пушкину (скульптор Г.В. Нерода, архитектор П.В. Бондаренко) изображает поэта в полный рост, – опираясь на утес, он смотрит на море. В Таганроге А.С. Пушкин был проездом 5 июня 1820 года во время путешествия по югу России вместе с семьей генерала Н.Н. Раевского. В день рождения поэта здесь по традиции собираются современные лирики, читают стихи и выпускают на волю птиц.', 'Пушкинская набережная', '00:00:00 00:00:00', NULL, 4.2, NULL, NULL, NULL, 'Таганрог', 47.21323454, 38.94038557);
INSERT INTO public.data VALUES (36, 'Гостиница «Горизонт»', 'Гостиницы', 'Гостиница', 'Гостиница располагает богатым номерным фондом и готова удовлетворить пожелания любого клиента, в гостинице «Горизонт» можно забронировать как стандартные номера так и номера повышенного комфорта.', 'ул. Богдана Хмельницкого, 2А', '00:00:00 00:00:00', 2000.00, 3.0, NULL, '8 (952) 578 11 35
8 (952) 579 6293
+7 903 436 80 03', 'rudik_sarksyan@mail.ru', 'Таганрог', 47.23680698, 38.88342027);
INSERT INTO public.data VALUES (48, 'Гостиница при Таганрогской Теннисной Академии', 'Гостиницы', 'Гостиница', 'Привлекательная Гостиница Теннисной Академии, где есть бесплатная парковка, парикмахерская и сауна, расположена в 3,8 км от Лавки Чеховых. Музей А.А. Дурова находится в 10 минутах езды от гостиницы Теннисной Академии. Отель расположен в тихом районе Таганрога, в 30 минутах ходьбы от центра города. Гости также могут посетить Каменную лестницу Депальдо.  Для удобства гостей номера оснащены балконом, электрочайником и мини-кухней. Здесь можно наслаждаться видом на террасу. К услугам гостей стиральная машина, стеклянная посуда и кухонная утварь, а также туалетные принадлежности, тапочки и полотенца. Бесплатный Wi-Fi предоставляется во всем отеле.', 'ул. Толбухина,7', '00:00:00 00:00:00', 3000.00, 3.0, NULL, '+7 (961) 320-40-20', 'ttatennis2007@yandex.ru', 'Таганрог', 47.25393814, 38.91965698);
INSERT INTO public.data VALUES (49, 'Гостиница «Ночной квартал»', 'Гостиницы', 'Гостиница', 'В перечнях вариантов отелей Таганрога с хорошими отзывами и высоким рейтингом, часто можно встретить мини-гостиницу «Ночной Квартал». Эксклюзивные рекомендации проживания. В избытке превосходных мест и достопримечательностей базируется недалеко с мини-гостиницей, например Дуб черешчатый в 700 метрах. Здесь можно снять чувство усталости. Прекрасное  время провождение с друзьями, да еще и с пользой для состояния здоровья. К тому же для удобства в отеле имеется открытый бассейн, где жильцы смогут принять водные ванны на свежем воздухе. До берега Азовского моря из номеров мини-гостиницы можно дойти пешком — расстояние составляет всего лишь 1.2 км. Пляж от мини-гостиницы отделяет расстояние 12 минут ходьбы. В номерах оборудованных кухней также есть принадлежности для кухни. Во всех хороших номерах предоставляется жк-телевизор с плоским экраном.', 'ул. Морозова, 37/2', '00:00:00 00:00:00', 2000.00, 3.8, NULL, '8 (928) 988-21-18', '-', 'Таганрог', 47.24572532, 38.91892022);
INSERT INTO public.data VALUES (25, 'Гостиница «НИКА»', 'Гостиницы', 'Гостиница', 'Гостиничный комплекс  (гостиница - 50 номеров, кафе, бильярдная, спорт зал)', 'пер. Трудовых резервов, 10', '00:00:00 00:00:00', 2000.00, 3.0, 'https://www.infotaganrog.ru/nika/', '8(8634)318-100', 'hotel-nika@mail.ru', 'Таганрог', 47.20915713, 38.88909119);
INSERT INTO public.data VALUES (22, 'Ресторан "Горец"', 'Еда', 'Ресторан', 'Открой для себя новый мир вкусов и ароматов настоящего кавказского гастрономического опыта! Ресторан кавказской кухни «Горец» приглашает в удивительное путешествие по культуре и традициям Кавказа. И вот 10 причин, по которым стоит посетить заведение:
1.Разнообразие блюд. Профессиональные повара готовят  самые изысканные и аутентичные кавказские блюда, которые завоюют ваше сердце с первого взгляда и укуса: Хинкали, Ишли-кюфта, Толма, Шашлык из мякоти теленка, Люля из раковых шеек, армянский суп «Спас», Хавурма, Хурджин, Бурата и многое другое.
2.Уникальный интерьер. Наслаждайтесь уютом и гостеприимством, которые так характерны для Кавказа.
3.Профессионализм персонала. Вам всегда готовы предложить качественный сервис и помощь с выбором блюд.
4.Музыка. Здесь вы можете насладиться мелодиями, которые дополнят твой ужин и создадут неповторимую атмосферу.
5.Богатый  выбор напитков. Широкий ассортимент  лимонадов и бодрящих коктейлей, подчеркивающих вкус и ароматы блюд.
6.Ресторан идеально подходит для проведения семейных праздников и мероприятий до 50 человек.
7.Большие порции: вы не уйдете голодными. Здесь всегда готовятся щедрые порции, чтобы насладиться полноценным обедом или ужином.
8.Доступные цены. Вы получите истинное удовольствие от еды, не переплачивая за это.
9.Скидки* в День рождения. По предъявлении паспорта скидка 10%.
10.Неповторимый опыт. Вы откроете для себя мир настоящей кавказской кухни и культуры, который оставит незабываемые впечатления и желание вернуться снова и снова.
Приходите в «Горец» и окунитесь в мир вкусов, ароматов и традиций Кавказа. Это место, где  каждый посетитель станет частью большой и дружной семьи!', 'ул. Петровская, 66Б', '11:00:00 00:00:00', 2000.00, 5.0, 'https://yandex.ru/maps/org/gorets/121829225309/?ll=38.934224%2C47.212334&z=17', '8-918-593-27-77', NULL, 'Таганрог', 47.2123366, 38.93422724);
INSERT INTO public.data VALUES (29, 'Отель «STAR CRYSTAL»', 'Гостиницы', 'Отель', 'Гостиничный комплекс «STAR CRYSTAL»  рад предложить Вам комфортабельный отдых на берегу Азовского моря.

К Вашим услугам:
шикарные апартаменты площадью 45 кв.м. состоящие из спальной комнаты, гостиной-студии со встроенной мини-кухней и балкона с видом на море
подогреваемый бассейн под открытым небом
круглосуточный Wi-Fi
детская игровая площадка
охраняемая территория
бесплатная автостоянка
сейфы в апартаментах
Все апартаменты оснащены душевой кабиной, системой кондиционирования воздуха, телевизорами последнего поколения, холодильником, электрической плитой, микроволновой печью, электрическим чайником, феном, утюгом, гладильной доской, кулером с очищенной водой, необходимыми кухонными принадлежностями (посуда для приготовления и приема пищи), столовыми принадлежностями, туалетными принадлежностями. Ванная комната. Wi-Fi. Холодильник. Телевизор.Бассейн.', 'ул. Адмирала Крюйса, 28 А', '00:00:00 00:00:00', 4000.00, 3.8, 'https://crystal-hotel.su/prices/', '+7 (8634) 43-12-55
+7 (929) 821-69-00', 'crystal.hotel2016@gmail.com', 'Таганрог', 47.22980831, 38.93473388);
INSERT INTO public.data VALUES (13, 'Street Gastro', 'Еда', 'Кафе', 'Уютное кафе в центре города, меню с традиционными блюдами донского региона. Одно из любимых блюд гостей города «Жареная тюлечка»', 'Тургеневский, 8', '10:00:00 23:00:00', 500.00, 4.0, NULL, NULL, NULL, 'Таганрог', 47.21195593, 38.93473911);
INSERT INTO public.data VALUES (18, 'Пури Пури', 'Еда', 'Кафе', 'Семейное бистро Пури Пури. Пури Пури каждому столу!', 'ул. Петровская, 98', '12:00:00 00:00:00', 1000.00, 0.0, NULL, NULL, NULL, 'Таганрог', 47.21681573, 38.92728061);
INSERT INTO public.data VALUES (75, 'Свято-Никольский храм', 'Места', 'Религиозные объекты', 'Храм святителя Николая Чудотворца — приходской храм Таганрогского благочиния Ростовской и Новочеркасской епархии Русской православной церкви.  Главная святыня — мощи святого Павла Таганрогского.', 'ул. Шевченко, 24', NULL, NULL, 4.5, NULL, NULL, NULL, 'Таганрог', 47.20167386, 38.9407194);
INSERT INTO public.data VALUES (23, 'Конгресс-отель «Таганрог»', 'Гостиницы', 'Гостиница', 'К услугам гостей 8 конференц-залов и 160 современно оформленных номеров с кабельным телевидением. В зонах общественного пользования предоставляется бесплатный Wi-Fi. Гости могут бесплатно посещать фитнес-центр.
В ресторане «Чехов» подают классические блюда европейской кухни. Для гостей сервируется завтрак «шведский стол».

Конгресс-отель «Таганрог» находится в 5 минутах езды от исторических достопримечательностей города. Поездка до железнодорожного вокзала Таганрога занимает 2 минуты.

Стойка регистрации конгресс-отеля «Таганрог» работает круглосуточно. Предоставляются услуги прачечной.

На территории обустроена частная парковка. Предоставляется трансфер до аэропорта.', 'ул. Дзержинского, 161', '00:00:00 00:00:00', 3300.00, 4.0, 'http://www.hoteltaganrog.ru/', '8 (8634) 68-30-03
+7 (919) 871-18-16', 'hotel-taganrog2014@yandex.ru', 'Таганрог', 47.25002951, 38.91730463);
INSERT INTO public.data VALUES (24, 'Гостиница «Золотой берег»', 'Гостиницы', 'Гостиница', 'В гостинице 14 номеров, из них 1- одноместный, 6-2х местных, 2 бюджетных номера «Стандарт», 4 категории «Люкс» и 1 Люкс апартаменты. 1-я линия от залива в исторической и деловой части города.', 'ул. Шмидта,16 а', '00:00:00 00:00:00', 3700.00, 4.0, 'http://gold-coast.ru/appart.htm', '8 (8634) 311-357
8 (8634) 311-563', 'info@gold-coast.ru', 'Таганрог', 47.21072095, 38.94256597);
INSERT INTO public.data VALUES (27, 'Гостиница «Южная ночь»', 'Гостиницы', 'Гостиница', 'Отель «Южная Ночь» в Таганроге — это отличный гостиничный сервис и многовариантность отдыха по умеренным ценам.
Популярность отеля — это его месторасположение в спокойном районе г. Таганрога, центральная часть отдельной территории спортивно-оздоровительного комплекса. Отель оснащен беспроводным доступом в интернет, что позволяет всегда оставаться на связи. 30 изысканно оформленных номеров, интерьер которых — это воплощение европейской лаконичности, обволакивающей своей цветовой палитрой и не довлеющей излишком деталей.
У нас созданы все условия для комфортного проживания в отеле, в том числе небольших делегаций и групп, которые кроме всего прочего, могут воспользоваться нашими дополнительными услугами: бильярдным залом и теннисными кортами.', 'ул. Ленина, 212 Б', '00:00:00 00:00:00', 2600.00, 3.0, 'https://hotelyuzhnaya-noch.ru/номера/', '8(8634)321-456
+7 903 400-02-21', 'yuzhnaya-noch@mail.ru', 'Таганрог', 47.23305807, 38.90836303);
INSERT INTO public.data VALUES (28, 'Оздоровительный гостевой дом «Зурбаган»', 'Гостиницы', 'Гостевой дом', 'Гостевой дом «Зурбаган» расположен в Таганроге, в 160 метрах от моря и песчаного пляжа. Все номера гостевого дома оформлены в индивидуальном стиле, каждый из которых оснащен телевизором с плоским экраном, транслирующим кабельные каналы, кроватью king size, холодильником, сплит-системой и собственным санузлом. Интерьер номеров выполнен в светлых тонах, располагающих к отдыху и настраивающих на спокойный сон. Гостевой дом расположен неподалеку от исторического центра Таганрога. В шаговой доступности аквапарк и термальный комплекс, в десяти минутах ходьбы Центральный парк культуры и отдыха им. М.Горького, а всего в пяти минутах Пушкинская набережная и – одна из главных достопримечательностей Таганрога – Каменная Лестница.', 'ул. Адмирала Крюйса, 2-Д', '00:00:00 00:00:00', 4000.00, 3.0, 'https://www.hotelzurbagan.com/', '+7 904 502-52-13', 'tabak_zwn@mail.ru', 'Таганрог', 47.22126601, 38.93554839);
INSERT INTO public.data VALUES (26, 'Отель «Гостиный двор»', 'Гостиницы', 'Гостиница', 'Расположение
От центра Таганрога до отеля — 4 км.
Номера
Номера оснащены многоканальным телевидением, гардеробной и системой климат-контроля, а также предлагают собственную ванную комнату. Для вашего комфорта предоставляется холодильник, микроволновая печь и чайник.
Отдых и бизнес
Гости также могут отдохнуть в сауне.
Интернет
Бесплатный Wi-Fi предоставляется во всем отеле.
Парковка
На территории предоставляется бесплатная частная парковка.', 'ул. Социалистическая,161', '00:00:00 00:00:00', 2600.00, 4.0, 'https://super-gostindvor.ru/', '8(8634) 327233', 'Super.gostindvor2013@yandex.ru', 'Таганрог', 47.25276786, 38.93430808);
INSERT INTO public.data VALUES (31, 'Гостевой дом «Форсаж»', 'Гостиницы', 'Гостевой дом', 'Отдельно стоящее здание с собственной парковкой во дворе.', 'ул. Октябрьская, 44Г', '00:00:00 00:00:00', 2800.00, 3.0, 'https://forsaj-t.narod.ru/', '8(8634)373-709', 'forsaj-t@yandex.ru', 'Таганрог', 47.22241412, 38.90833243);
INSERT INTO public.data VALUES (32, 'Гостевой дом «Ренессанс»', 'Гостиницы', 'Гостевой дом', 'Гостевой дом «Ренессанс» расположен в центре города Таганрога. К услугам гостей номера класса комфорт. Во всех номерах есть кондиционер, телевизор с плоским экраном, чайник, предоставляется постельное белье и полотенца, а также в номере собственная ванная комната. К услугам гостей круглосуточная стойка регистрации и охраняемая автостоянка, трансфер от/до аэропорта Платова, доставка еды и напитков в номер и бесплатный Wi-Fi. В шаговой доступности центральный рынок, рынок Радуга, ж/д и автовокзал, а также большое количество кафе и столовых. В числе популярных достопримечательностей рядом с гостевым домом «Ренессанс» Драматический театр им. А.П. Чехова, музей А.А. Дурова и Таганрогский художественный музей, а так же центральный парк им. М.Горького.', 'ул. Октябрьская, 24', '00:00:00 00:00:00', 3000.00, 3.8, 'www.renshotel.ru', '+7 928 774 48 58', 'renshotel24@gmail.com', 'Таганрог', 47.21731881, 38.91895613);
INSERT INTO public.data VALUES (33, 'Гостиница «Маликон»', 'Гостиницы', 'Гостиница', 'Гостиница «Маликон» — это современные номера, оборудованные всем необходимым для комфортного проживания. Отличным дополнением к отдыху каждого клиента может стать посещение бассейнов с подогревом как закрытых, так и открытых, детской площадки, оборудованной всем необходимым для детей, спорт площадки, ресторана, как идеального места для проведения корпоративов и свадебных мероприятий, также вы можете посетить сауну: инфракрасную и финскую, которые функционируют каждый день на территории парк-отеля. Полноценный отдых днем и яркое времяпровождение ночью — это вполне реально. Гостиница «Маликон» одна из лучших гостиниц в Таганроге. Недалеко от «Парк-Отель Маликон» находятся — Приморский Парк, пляж, набережная, с многочисленными кафе и видом на Азовское море. Гостиницы Таганрога европейского уровня предоставляют прекрасную возможность разрешать все деловые вопросы во время пребывания, а также незабываемо, по южному провести досуг в Таганроге.', 'ул. Энергетическая, 125', '00:00:00 00:00:00', 3800.00, 3.0, 'http://malikon.ru/', '8(8634)649-393', 'admin@malikon.ru', 'Таганрог', 47.21674024, 38.88655132);
INSERT INTO public.data VALUES (34, 'Гостиница «Темиринда»', 'Гостиницы', 'Гостиница', 'Гостиница расположена на северо-восточной части побережья Таганрогского залива, напротив городского яхт-клуба. Расположение отеля сочетает в себе как близость к излюбленным местам отдыха жителей Таганрога, так и пешеходную доступность деловой части города. Рядом с гостиницей расположен городской пляж, аквапарк и Пушкинская набережная - главная пешеходная зона Таганрога. 47 комфортабельных номеров: Все номера оснащены: автономной системой кондиционирования с индивидуальным регулированием, мини холодильником (бар), телефоном, ванной/душем, панорамным остеклением (категории "Люкс-студия", "Полу-люкс"), бесплатным Wi-Fi, охранными системами. Ресторан на 60 посадочных мест. Бар на 7 посадочных мест. Конференц-зал, интернет. Банкетный зал. Охраняемая автопарковка. Велнесс-центр. Хаммам. Массаж. Соляной грот. Террасы для отдыха. Ресторанная площадка на открытом воздухе.Культурные и оздоровительные программы.', 'ул. Портовая, 1/2', '00:00:00 00:00:00', 2050.00, 4.0, 'https://www.temirinda.ru/', '8(8634)321-122
+7(938)103-40-01', 'temirinda@gmail.com', 'Таганрог', 47.20762047, 38.94981466);
INSERT INTO public.data VALUES (35, 'Гостиница «Ассоль»', 'Гостиницы', 'Гостиница', 'Гостинично-ресторанный комплекс «Ассоль» 2* - это: 59 номеров различных категорий: от шикарных «Апартаментов» до демократичных «Стандартов»; 2 банкетных зала ресторана различной вместимости (60 и 15 чел.); конференц-зал с оборудованием (проектор, экран, флипчарты, рабочие наборы); оборудование для организации выездного обслуживания – кейтеринга; 7-местный минивэн для осуществления междугородних и внутригородских перевозок; живописный летний сад с площадкой для выездных регистраций. Гостиница подойдет как отдыхающим - в связи с близостью к Приморскому парку и пляжу, так и бизнес-командировочным.', 'ул. Инструментальная, 31 корп. 2', '00:00:00 00:00:00', 2850.00, 5.0, 'http://assol-hotel.ru/', '8(8634)341-613', 'assoltag@gmail.com', 'Таганрог', 47.19940976, 38.8873695);
INSERT INTO public.data VALUES (37, 'Гостевой дом «Надежда»', 'Гостиницы', 'Гостевой дом', 'Гостевой дом «Надежда» предоставляет элитные номера для временного проживания на месяц, сутки и почасовое: различные номера от эконом-класса до апартаментов; бесплатный Wi-Fi; высокоскоростной интернет; во всех номерах кондиционеры, ж/к телевизоры, холодильник, санузлы с душем или ванной, жалюзи; вся необходимая бытовая техника в ассортименте; чистота и уют - наши основополагающие принципы; охраняемая автостоянка и парковка; группам предоставляются коллективные скидки; различные завтраки, трансфер, стирка, глажка, сейф и др. услуги; имеются детские принадлежности (кроватка, коляска, ходунки, ванночка и т.д.). Хостел европейского уровня единственный в городе Таганроге. В него входит 3 номера 6-ти местных и 3 номера 8-ми местных, 1 номер 12-ти местный. В номерах имеются кондиционеры, телевизоры, холодильники, кровати, шкафы, комоды, стулья, письменные столы. Полностью оборудованная кухня, комната отдыха (банкетный зал), 4 санузла, 2 душевые кабинки, также есть 2 стиральные машины, сушилка и гладилка для вещей.', 'ул. Чехова, 156', '00:00:00 00:00:00', 2600.00, 5.0, 'http://nadezda-hotel.ru/', '8 (8634) 351-061
9-989-50-50-551', 'nadezda-hotel@ya.ru
n-esipenko@yandex.ru', 'Таганрог', 47.21593516, 38.9062869);
INSERT INTO public.data VALUES (38, 'Гостиница «Извольте»', 'Гостиницы', 'Гостиница', 'Все интерьеры гостиницы стилизованы под классицизм. В ней 7 номеров (одно- и двухместные) категории люкс. Светлые окна выходят на тихий сквер в пер. Спартаковском. Все номера оборудованы импортной мебелью, имеется вся необходимая бытовая техника. Кроме этого, в каждом номере вы найдете телевизор со спутниковым телевидением, телефон и мини бар. Для постояльцев предусмотрена возможность питания в ресторане «Извольте», завтрак и прохладительные напитки могут быть доставлены прямо в номер. У территории комплекса можно безбоязненно оставить легковой автотранспорт.', 'ул. Октябрьская, 16', '00:00:00 00:00:00', 3500.00, 5.0, 'https://izvolte.info/hotel', '8 (8634) 314-098', 'izvolte@mail.ru', 'Таганрог', 47.21574933, 38.9222481);
INSERT INTO public.data VALUES (39, 'Бутик-отель «Варваци»', 'Гостиницы', 'Гостиница', 'Гостиница Таганрога - Бутик-отель «Варваци» расположен в историческом центре, гостиница является объектом культурного наследия, памятником жилой архитектуры XIX века города Таганрога, находится в живописном месте на побережье Азовского моря. Одной из главных привлекательных особенностей гостиницы является удобное расположение в самом центре города, где находятся все важные административные и бизнес-объекты, удобные для решения деловых задач. Гостиница находится в Таганроге в непосредственной близости от аквапарка «Лазурный», пляжа «Солнечный», яхт-клуба и Пушкинской набережной.', 'ул. Греческая, 76', '00:00:00 00:00:00', 4100.00, 5.0, 'http://varvaci.ru/', '8 (8634) 319-001
+7 919 883-45-15', 'mail@varvaci.ru', 'Таганрог', 47.2143835, 38.93429824);
INSERT INTO public.data VALUES (40, '«Гринвич Парк Отель и СПА»', 'Гостиницы', 'Гостиница', 'Спа-отель «Гринвич Парк» расположен в 1 км от центра Таганрога, на Пушкинской набережной, всего в 20 метрах от берега Азовского моря. К услугам гостей спа-центр и бесплатный Wi-Fi. Все светлые номера оборудованы кондиционером и телевизором. В ванной комнате каждого номера предоставляются бесплатные туалетно-косметические принадлежности, тапочки и фен. В ресторане СПА-отеля подаются различные блюда русской и европейской кухни. На территории отеля «Гринвич Парк» имеется открытый бассейн с террасой для загара. Гости могут бесплатно пользоваться сауной или паровой баней, а также заказать услуги массажа за дополнительную плату. Депальдовская лестница находится в 2 км от отеля. Расстояние до центрального вокзала Таганрога составляет 4 км, а до международного аэропорта Ростова-на-Дону — 87 км.', 'ул. Адмирала Крюйса, 2А', '00:00:00 00:00:00', 6000.00, 4.0, 'https://greenwich-park.ru/hotels', '8(8634)32-42-42
+7(989)512-08-33', 'greenwichpark@mail.ru', 'Таганрог', 47.2196084, 38.93822286);
INSERT INTO public.data VALUES (41, '«Greenwich City Hotel»', 'Гостиницы', 'Гостиница', 'Отель Greenwich City by Greenwich Park расположен в Таганроге, менее чем в 1 км от музея Дурова. К услугам гостей открытый бассейн, номера для некурящих, бесплатный WiFi и общий лаундж. К услугам гостей этого 2-звездочного отеля круглосуточная стойка регистрации и общая кухня. Собственная ванная комната с душем укомплектована феном и бесплатными туалетно-косметическими принадлежностями. Номера отеля оснащены телевизором с плоским экраном и спутниковыми каналами. Каждое утро в отеле Greenwich City подают завтрак по меню. Рядом с отелем можно заняться различными видами активного отдыха. Популярные достопримечательности вблизи отеля Greenwich City by Greenwich Park включают Таганрогский художественный музей, Чеховский драматический театр и парк Горького. Расстояние до международного аэропорта Платова составляет 103 км.', 'пер. Красный, 14А', '00:00:00 00:00:00', 2600.00, 5.0, 'https://greenwich-park.ru/hotels', '8 (8634) 314-242
+7 951 839-85-83', 'greenwichpark@mail.ru', 'Таганрог', 47.21424794, 38.92372294);
INSERT INTO public.data VALUES (42, '«Pink''s Family Hotel & SPA»', 'Гостиницы', 'Гостиница', 'Спа-отель Pink''s Family by Greenwich Park занимает отреставрированное здание XIX века в историческом центре города Таганрог. К услугам гостей бесплатный Wi-Fi. Во всех номерах имеются телевизор, кондиционер и индивидуальная система отопления. Предоставляются бокалы для вина. В числе удобств собственная ванная комната с бесплатными туалетно-косметическими принадлежностями и феном. В при отеле работает спа-комплекс, где можно бесплатно посещать аквазону с бассейном, паровой баней, сауной и помещением для соляной терапии. Прогулка до Парка культуры и отдыха имени Горького займет 5 минут, а до Пушкинской набережной — 15 минут. Расстояние до аэропорта Ростов-на-Дону составляет 66 км.', 'ул. Петровская, 80', '00:00:00 00:00:00', 5100.00, 5.0, 'https://greenwich-park.ru/hotels', '8(8634)314-242
+7 951 524-93-29', 'greenwichpark@mail.ru', 'Таганрог', 47.21493311, 38.93032184);
INSERT INTO public.data VALUES (43, 'Гостиница «Бристоль-Центральная»', 'Гостиницы', 'Гостиница', 'Гостиница «Бристоль-Центральная» расположен в центре города Таганрог, в его историческом, культурном и деловом центре, который прекрасно сочетает в себе деловую активность, сферу развлечений и спокойную размеренную жизнь.', 'ул. Петровская, 64', '00:00:00 00:00:00', 4300.00, 4.6, 'http://bristolhotel.ru/', '8 (8634) 383-022', 'admin@bristolhotel.ru', 'Таганрог', 47.2120492, 38.93473302);
INSERT INTO public.data VALUES (45, 'Гостиница «Приазовье»', 'Гостиницы', 'Гостиница', 'Современный гостиничный комплекс, расположенный в городе Таганрог, на берегу Азовского моря. В Вашем распоряжении комфортные номера с различным интерьером, ресторан с превосходной кухней, большая открытая территория с розариями и собственным пляжем, бассейном под открытым небом и теннисный корт. Так же есть все необходимые условия для проведения бизнес-встреч и конференций. Прекрасное место для семейного отдыха.', 'ул. Бабушкина, 2Д', '00:00:00 00:00:00', 3800.00, 5.0, 'https://priazovie-spa.ru/', '8 (8634) 320-015', 'priazovye.spa@mail.ru', 'Таганрог', 47.2494835, 38.93504865);
INSERT INTO public.data VALUES (46, 'Гостиница «Восточная»', 'Гостиницы', 'Гостиница', 'Гостиница «Восточная» с бесплатным Wi-Fi на всей территории находится в Таганроге. Номера оснащены телевизором с плоским экраном. Стойка регистрации работает круглосуточно. Расстояние до ближайшего аэропорта Ростова-на-Дону составляет 69 км.', 'ул. Восточная, 8', '00:00:00 00:00:00', 2500.00, 4.0, 'https://vostochnaya.rhotel.site/', '8-989-624-24-27', 'dashtamirov51@mail.ru', 'Таганрог', 47.23592413, 38.89157983);
INSERT INTO public.data VALUES (47, 'Гостиница «Крыжовник»', 'Гостиницы', 'Гостевой дом', 'Это семейный отель в шаговой доступности от берега Азовского моря, близ религиозных и музейных ценностей.', 'ул. Шевченко, 130В', '00:00:00 00:00:00', 2800.00, 4.0, 'https://kryzhovnik-taganrog.ru/', '+7 (903) 400-11-71
+7 (918) 552-85-11', 'kryzhovnik-taganrog@yandex.ru
central-dom@yandex.ru', 'Таганрог', 47.20100328, 38.92202741);
INSERT INTO public.data VALUES (44, 'Гостевой "Дом Плотниковых"', 'Гостиницы', 'Гостевой дом', 'Гостевой Дом Плотниковых расположен в центре Таганрога. Дом построен в 2008 году в стиле архитектуры начала ХХ века. В Гостевом Доме 5 этажей и башня, в которой установлены куранты. Каждый час, с 8:00 до 20:00, сопровождается перезвоном пяти малых колоколов и боем большого колокола. Интернет и дизайн комнат, художественная роспись стен помогает представить себя в старом провинциальном Таганроге, каким видел его ещё А.П. Чехов. Месторасположение Гостевого Дома позволяет совместить работу и пляжный отдых на Азовском море, а также осуществлять пешие прогулки по старому городу, набережной и центральному парку. В шаговой доступности от Дома расположены бутики, продуктовые магазины, офисы, муниципальные и государственные организации.', 'ул. Петровская, 37А', '00:00:00 00:00:00', 3100.00, 3.0, 'https://plotnikov-dom.ru/ru/', '8 (8634) 327-100', 'plotnikov-dom@mail.ru', 'Таганрог', 47.21035396, 38.93639343);
INSERT INTO public.data VALUES (50, 'Мини-гостиница «Отель Наутилус и СПА»', 'Гостиницы', 'Гостиница', 'Гостиница расположена в Таганроге, всего в 2,5 км от Приморского пляжа — удобное место как для отдыха у моря, так и для деловых поездок. К услугам гостей — ресторан, бесплатная частная парковка,  уютный общий лаундж для отдыха, круглогодичный подогреваемый закрытый бассейн с водными аттракционами, сауны, русская баня на дровах и банные процедуры.

Это 3-звездочный отель с тёплой атмосферой и вниманием к каждому гостю. Здесь работают:
- доставка еды и напитков в номер,
- экскурсионное бюро,
- общая кухня,
- бесплатный Wi-Fi,
- трансфер от и до аэропорта.

Включено в стоимость: по утрам гостям предлагают на выбор континентальный завтрак или завтрак по меню, а также 1 час посещения бассейна.

Любителям культурного отдыха будет удобно: всего в 10 минутах езды — музей А.А. Дурова и Таганрогский художественный музей.

«Отель Наутилус и СПА» — место, куда хочется возвращаться.', 'Поляковское шоссе, 18', '00:00:00 00:00:00', 2600.00, 5.0, 'https://hotel-taganrog.com/', '8 (8634) 64-55-55
+7 969 124-90-10', 'akvaklub_nautilus@mail.ru', 'Таганрог', 47.21088373, 38.86363856);
INSERT INTO public.data VALUES (51, 'Гостиница «Топаз»', 'Гостиницы', 'Гостиница', 'Отель «Центр Здоровья Топаз» с рестораном, садом и бесплатной частной парковкой расположен в Таганроге, в 2,1 км от пляжа. До парка культуры и отдыха имени Горького — 1,4 км, до Таганрогского драматического театра имени А. П. Чехова — 1,6 км, а до Таганрогского художественного музея — 2,6 км. В отеле работает круглосуточная стойка регистрации и осуществляется доставка еды и напитков в номер. К услугам гостей бесплатный Wi-Fi. Для гостей организуют трансфер от/до аэропорта. В номерах установлен шкаф для одежды, предоставляется постельное белье. В числе удобств балкон с видом на сад. Все номера отеля «Центр Здоровья Топаз» оснащены телевизором с кабельными каналами. Расстояние до Музея А. А. Дурова составляет 2,7 км. От отеля «Центр Здоровья Топаз» до международного аэропорта Платов — 81 км.', 'ул. Адмирала Крюйса, 2/12', '00:00:00 00:00:00', 2000.00, 3.0, 'https://cz-topaz.ru/', '8(8634)327-859', 'ok-adria@mail.ru', 'Таганрог', 47.22003467, 38.93656341);
INSERT INTO public.data VALUES (52, 'Гостиница "Ида"', 'Гостиницы', 'Гостиница', 'Отель «Ида» находится в историческом центре г.Таганрога. Дому, в котором находится отель, более 170 лет.

У гостиницы есть свое собственное кафе "Фрекен Бок", которое работает  каждый день с 8 00 до 22 00. В кафе разнообразное полноценное меню, кофе, чай и десерты собственного изготовления.

В шаговой доступности расположены самые интересные музеи и достопримечательности города: места, связанные с именами великих людей, родившихся в Таганроге, - писателя Антона Павловича Чехова и актрисы Фаины Георгиевны Раневской.
Художественный музей с полотнами И.К. Айвазовского, Ф. С. Рокотова, В. И. Сурикова находится в 100 м от отеля. Спуститься к морю по старой Каменной лестнице можно в течение 10 минут.', 'пер. Тургеневский, 22', '00:00:00 00:00:00', 3900.00, 5.0, 'https://idahotel.ru/', '+7 (928) 6195 317', 'idahoteltaganrog@gmail.com
frekenbok_kafe@mail.ru', 'Таганрог', 47.2109031, 38.93229092);
INSERT INTO public.data VALUES (17, 'Робин Бобин', 'Еда', 'Кафе', 'Кафе «Робин-Бобин» расположено на центральной улице города Таганрога.

Интерьер заведения выполнен в светлых тонах. Маленькие столики, много света, картины и фотографии на стенах – все это создает атмосферу уюта.

В меню ресторана представлены блюда европейской кухни, а также большой выбор кондитерских изделий.', 'Петровская, 55', '09:00:00 21:00:00', 400.00, 5.0, NULL, NULL, NULL, 'Таганрог', 47.21231501, 38.93364191);
INSERT INTO public.data VALUES (19, 'Мандарин', 'Еда', 'Ресторан', 'Ресторан «Мандарин» предлагает своим гостям блюда паназиатской кухни, приготовленные по традиционным китайским рецептам. Интерьер ресторана выполнен в аутентичном китайском стиле, с мягкими диванами и множеством деталей, напоминающих о китайской культуре.', 'ул.Петровская, 88', '11:00:00 00:00:00', 1500.00, 0.0, NULL, NULL, NULL, 'Таганрог', 47.21585995, 38.92883858);
INSERT INTO public.data VALUES (20, 'Осака', 'Еда', 'Кафе', 'Суши-бар «Осака» предлагает своим гостям широкий выбор блюд японской кухни, таких как суши, роллы, мидии, салаты и бургеры. Интерьер заведения выполнен в классическом стиле с кирпичной кладкой и деревянными элементами, что создает уютную атмосферу.', 'ул. Петровская, 84', '11:00:00 23:00:00', 900.00, 0.0, NULL, NULL, NULL, 'Таганрог', 47.21544884, 38.92976883);
INSERT INTO public.data VALUES (30, 'Гостиница «Сеновал»', 'Гостиницы', 'Гостиница', 'Уютная, бюджетная, комфортная гостиница. Находится на въезде в Таганрог со стороны Мариупольского шоссе. Рядом ТЦ "Калинка", развитая инфраструктура, общественный транспорт.', 'Мариупольское шоссе, 31', '00:00:00 00:00:00', 2300.00, 4.0, NULL, NULL, NULL, 'Таганрог', 47.22548531, 38.85596234);
INSERT INTO public.data VALUES (53, 'Гостиница "Петровский Двор"', 'Гостиницы', 'Гостиница', 'Гостиница «Петровский Двор» расположена в особняке середины XIX века в самом сердце исторической части Таганрога. Здание, принадлежавшее купцу 1-й гильдии, главе города Ивану Кобылину, ныне является объектом культурного наследия регионального значения.

«Петровский двор» предлагает гостям уютные номера и апартаменты, которые обеспечат комфортный отдых после активного дня. В каждом номере — удобные кровати, телевизор, кондиционер, санузел с душем, туалетные принадлежности, телефон, бесплатный Wi-Fi, холодильник. В стоимость проживания в гостинице входит вкусный завтрак.

На первом этаже гостиницы располагается ресто-бар в винтажном стиле с прекрасной кухней. В шаговой доступности — магазины, кафе, скверы, музеи, набережная, пляжи, театр имени Чехова и парк Горького.', 'ул. Петровская, 49', '00:00:00 00:00:00', 4300.00, 4.0, 'https://petrovskiydvor-taganrog.ru/', '8 (8634) 61‒97‒19
+7(988)999-65-60', 'petrovskiydvor@yandex.ru', 'Таганрог', 47.2119825, 38.9342602);
INSERT INTO public.data VALUES (54, 'Санаторий-профилакторий «Тополь»', 'Гостиницы', 'Отель', 'Санаторий расположен на берегу Азовского моря. Такой вид климатолечения, как таласcотерапия (морские купания под открытым небом) наиболее благоприятно сказывается при лечении заболеваний щитовидной железы, нервной системы, атеросклероза, гипертонии и других недугов. Зеленую зону санатория, площадью 4 Га, формируют более 400 хвойных и лиственных деревьев, вечнозеленых кустарников, запах хвои в сочетании с морским воздухом благотворно влияет на здоровье отдыхающих в любое время года.', 'ул. Социалистическая, 170', '08:00:00 18:00:00', 2000.00, 0.0, 'http://priazovie-spa.ru/sanatorij', '8 (8634) 343-451', 'priazovye.spa@mail.ru', 'Таганрог', 47.25133823, 38.93562864);
